import { test, expect } from '@playwright/test';

test.describe('Async PDF Generation Download', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/generate-pdf');
  });

  test('should generate and download PDF when button is clicked', async ({ page }) => {
    // Verify initial page content
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await expect(generateButton).toBeVisible();

    // Click the generate button
    await generateButton.click();

    // Wait for PDF generation to complete
    const downloadPromise = page.waitForEvent('download');

    // Verify download dialog appears
    const downloadDialog = page.getByRole('dialog', { name: /download pdf/i });
    await expect(downloadDialog).toBeVisible();

    // Verify download link is present
    const downloadLink = page.getByRole('link', { href: /.pdf$/i });
    await expect(downloadLink).toBeVisible();

    // Verify download button is visible
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeVisible();

    // Click the download button
    await downloadButton.click();

    // Verify download file appears in downloads folder
    const downloadFolder = page.getByRole('navigation', { name: /downloads/i });
    await expect(downloadFolder).toBeVisible();

    const downloadFile = page.getByText(/my-document.pdf/i);
    await expect(downloadFile).toBeVisible();

    // Verify file size is not zero
    const fileSize = page.getByText(/bytes/i);
    await expect(fileSize).toContainText('12345');

    // Verify file is not empty
    const fileContent = page.getByText(/content/i);
    await expect(fileContent).toBeVisible();

    // Verify download dialog is closed
    await expect(downloadDialog).not.toBeVisible();
  });

  test('should handle failed PDF generation and display error message', async ({ page }) => {
    // Mock PDF generation API to fail
    await page.route('**/api/generate-pdf', (route) => {
      route.abort('Failed to generate PDF');
    });

    // Click the generate button
    const generateButton = page.getByRole('button', { name: /generate pdf/i });
    await expect(generateButton).toBeVisible();
    await generateButton.click();

    // Wait for error state
    const errorMessage = page.getByText(/failed to generate pdf/i);
    await expect(errorMessage).toBeVisible();

    // Verify error dialog appears
    const errorDialog = page.getByRole('dialog', { name: /failed to generate pdf/i });
    await expect(errorDialog).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify download button is not visible
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).not.toBeVisible();

    // Verify error message is displayed
    await expect(errorMessage).toContainText('Failed to generate PDF');

    // Verify error dialog is closed when retry is clicked
    const retryButton = page.getByRole('button', { name: /retry/i });
    await retryButton.click();

    await expect(errorMessage).not.toBeVisible();
  });
});
